// Data Batas Wilayah PC & Jaringan Pipa Distribusi dari shapefile Batas PC.shp (UTM Zone 48S -> WGS84)

export interface PCBoundaryArea {
  id: string;
  name: string;
  shortName: string;
  region: string;
  description: string;
  nominalPressureBar: number;
  toleranceBar: number;
  color: string;
  fillColor: string;
  pipeCount: number;
  totalLengthKm: number;
  center: [number, number]; // [lat, lng]
  polygon: [number, number][]; // [[lat, lng], ...]
}

export interface PrimaryPipeLine {
  id: string;
  pcId: string;
  diameter: number;
  material: string;
  networkType: string;
  lengthMeters: number;
  contractor: string;
  yearLaid: string;
  coordinates: [number, number][]; // [[lat, lng], ...]
}

